import cors from "cors";

const allowed = (process.env.CORS_ORIGINS ?? "http://localhost:5173").split(",");

app.use(
  cors({
    origin(origin, cb) {
      if (!origin || allowed.includes(origin)) return cb(null, true);
      cb(new Error("CORS blocked"));
    },
    credentials: true,
  }),
);
